from collections import deque

class Solution:
    def minPushBox(self, grid):
        m, n = len(grid), len(grid[0])
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 'S': p = (i, j)
                elif grid[i][j] == 'B': b = (i, j)
                elif grid[i][j] == 'T': t = (i, j)

        def reach(start, goal, box):
            stack, seen = [start], {start}
            while stack:
                r, c = stack.pop()
                if (r, c) == goal:
                    return True
                for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in seen \
                            and grid[nr][nc] != '#' and (nr, nc) != box:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            return False

        q = deque([(b[0], b[1], p[0], p[1], 0)])
        seen = {(b, p)}
        while q:
            br, bc, pr, pc, d = q.popleft()
            if (br, bc) == t:
                return d
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nbr, nbc, spr, spc = br + dr, bc + dc, br - dr, bc - dc
                if not (0 <= nbr < m and 0 <= nbc < n and 0 <= spr < m and 0 <= spc < n):
                    continue
                if grid[nbr][nbc] == '#' or grid[spr][spc] == '#':
                    continue
                if not reach((pr, pc), (spr, spc), (br, bc)):
                    continue
                ns = ((nbr, nbc), (br, bc))
                if ns not in seen:
                    seen.add(ns)
                    q.append((nbr, nbc, br, bc, d + 1))
        return -1

