import java.util.*;

class Solution {
    public int minPushBox(char[][] g) {
        int m = g.length, n = g[0].length;
        int[] b = null, p = null, t = null;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                if (g[i][j] == 'S') p = new int[]{i, j};
                else if (g[i][j] == 'B') b = new int[]{i, j};
                else if (g[i][j] == 'T') t = new int[]{i, j};
            }
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        PriorityQueue<long[]> pq = new PriorityQueue<>((x, y) -> Long.compare(x[0], y[0]));
        Map<Long, Integer> best = new HashMap<>();
        long startKey = key(b[0], b[1], p[0], p[1]);
        best.put(startKey, 0);
        pq.offer(new long[]{heur(b, t), 0, b[0], b[1], p[0], p[1]});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int d = (int) cur[1], br = (int) cur[2], bc = (int) cur[3], pr = (int) cur[4], pc = (int) cur[5];
            if (br == t[0] && bc == t[1]) return d;
            for (int[] dir : dirs) {
                int nbr = br + dir[0], nbc = bc + dir[1];
                int spr = br - dir[0], spc = bc - dir[1];
                if (Math.min(Math.min(nbr, nbc), Math.min(spr, spc)) < 0
                        || nbr >= m || nbc >= n || spr >= m || spc >= n) continue;
                if (g[nbr][nbc] == '#' || g[spr][spc] == '#') continue;
                if (!reach(g, pr, pc, spr, spc, br, bc)) continue;
                long k = key(nbr, nbc, br, bc);
                Integer prev = best.get(k);
                if (prev == null || prev > d + 1) {
                    best.put(k, d + 1);
                    int[] nb = {nbr, nbc};
                    pq.offer(new long[]{d + 1 + heur(nb, t), d + 1, nbr, nbc, br, bc});
                }
            }
        }
        return -1;
    }

    private long heur(int[] bpos, int[] t) {
        return Math.abs(bpos[0] - t[0]) + Math.abs(bpos[1] - t[1]);
    }

    private long key(int br, int bc, int pr, int pc) {
        return ((long) br << 45) | ((long) bc << 30) | ((long) pr << 15) | pc;
    }

    private boolean reach(char[][] g, int sr, int sc, int tr, int tc, int br, int bc) {
        int m = g.length, n = g[0].length;
        boolean[][] vis = new boolean[m][n];
        Deque<int[]> st = new ArrayDeque<>();
        st.push(new int[]{sr, sc});
        vis[sr][sc] = true;
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!st.isEmpty()) {
            int[] cur = st.pop();
            if (cur[0] == tr && cur[1] == tc) return true;
            for (int[] d : dirs) {
                int nr = cur[0] + d[0], nc = cur[1] + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !vis[nr][nc]
                        && g[nr][nc] != '#' && !(nr == br && nc == bc)) {
                    vis[nr][nc] = true;
                    st.push(new int[]{nr, nc});
                }
            }
        }
        return false;
    }
}

