    const heap = [[heur(b[0], b[1]), 0, b[0], b[1], p[0], p[1]]];
    const pop = () => {
        const top = heap[0], last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            while (true) {
